{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2159-12-10 17:30:00",
      "speaker": "Doctor",
      "text": "Hello Mr. ___, I'm Dr. ___, one of your hospital doctors. You've just come back from your TACE procedure, and I wanted to check in on how you're feeling."
    },
    {
      "turn_number": 2,
      "time": "2159-12-10 17:31:00",
      "speaker": "Patient",
      "text": "Hi, doctor. I’m feeling okay—no pain or anything. A little tired, but that’s about it."
    },
    {
      "turn_number": 3,
      "time": "2159-12-10 17:32:00",
      "speaker": "Doctor",
      "text": "That’s good to hear. The team said the procedure went well. They targeted a tumor in segment VIII of your liver using chemo-embolization through the right hepatic artery."
    },
    {
      "turn_number": 4,
      "time": "2159-12-10 17:33:00",
      "speaker": "Patient",
      "text": "Was it the same spot as before? I remember last time was tough."
    },
    {
      "turn_number": 5,
      "time": "2159-12-10 17:34:00",
      "speaker": "Doctor",
      "text": "This is a different area—segment VIII, which showed up on your recent MRI. It’s about 2.7 cm and met criteria for treatment. They used doxorubicin-loaded beads to target it."
    },
    {
      "turn_number": 6,
      "time": "2159-12-10 17:35:00",
      "speaker": "Patient",
      "text": "Did they get all of it? I’m worried it might come back again."
    },
    {
      "turn_number": 7,
      "time": "2159-12-10 17:36:00",
      "speaker": "Doctor",
      "text": "The imaging shows successful embolization. There was a small possible supply from the left hepatic artery, but it was very minor and not treatable this time. The main feeding vessel was fully treated."
    },
    {
      "turn_number": 8,
      "time": "2159-12-10 17:37:00",
      "speaker": "Patient",
      "text": "Okay, that’s a relief. Do I need a CT scan after this?"
    },
    {
      "turn_number": 9,
      "time": "2159-12-10 17:38:00",
      "speaker": "Doctor",
      "text": "No CT needed this time. The real-time imaging during the procedure confirmed good delivery. You’ll have a follow-up MRI in about a month to check the response."
    },
    {
      "turn_number": 10,
      "time": "2159-12-10 19:15:00",
      "speaker": "Doctor",
      "text": "Just checking in again. Any nausea, fever, or pain since the procedure?"
    },
    {
      "turn_number": 11,
      "time": "2159-12-10 19:16:00",
      "speaker": "Patient",
      "text": "No, still feeling fine. My leg where they went in feels okay—no bleeding or swelling."
    },
    {
      "turn_number": 12,
      "time": "2159-12-10 19:17:00",
      "speaker": "Doctor",
      "text": "Good. The closure device worked well, and your pulse is strong down there. We’re keeping an eye out for post-embolization syndrome, but so far, so good."
    },
    {
      "turn_number": 13,
      "time": "2159-12-11 08:00:00",
      "speaker": "Doctor",
      "text": "Morning. Your labs came back. Your blood counts are stable—white count and platelets are low but unchanged from before. Liver enzymes are slightly up, which is expected."
    },
    {
      "turn_number": 14,
      "time": "2159-12-11 08:01:00",
      "speaker": "Patient",
      "text": "Is that a problem? My numbers are always a bit off because of my liver."
    },
    {
      "turn_number": 15,
      "time": "2159-12-11 08:02:00",
      "speaker": "Doctor",
      "text": "Exactly. Given your cirrhosis, these are actually reassuring. Your glucose is better today—147—down from 226 yesterday. Probably because you were fasting for the procedure."
    },
    {
      "turn_number": 16,
      "time": "2159-12-11 08:03:00",
      "speaker": "Patient",
      "text": "I’ve been watching my sugar, but it’s hard sometimes. What about my other meds?"
    },
    {
      "turn_number": 17,
      "time": "2159-12-11 08:04:00",
      "speaker": "Doctor",
      "text": "You’ll go home on all your usual meds—furosemide, spironolactone, nadolol, rifaximin, and your diabetes pills. We’re adding a nausea medicine—prochlorperazine—just in case you feel queasy over the next few days."
    },
    {
      "turn_number": 18,
      "time": "2159-12-11 08:05:00",
      "speaker": "Patient",
      "text": "Okay, thanks. And I should call if I get a fever?"
    },
    {
      "turn_number": 19,
      "time": "2159-12-11 08:06:00",
      "speaker": "Doctor",
      "text": "Yes—any fever over 100.4, significant pain, or nausea you can’t control, please call your liver team. Otherwise, keep your follow-up appointment in two weeks."
    },
    {
      "turn_number": 20,
      "time": "2159-12-11 08:07:00",
      "speaker": "Patient",
      "text": "Got it. So I can go home today?"
    },
    {
      "turn_number": 21,
      "time": "2159-12-11 08:08:00",
      "speaker": "Doctor",
      "text": "Yes, if you’re feeling well and your vitals stay stable. You’re alert, walking fine, and your exam looks good. We’ll get your discharge papers ready."
    },
    {
      "turn_number": 22,
      "time": "2159-12-11 08:09:00",
      "speaker": "Patient",
      "text": "I’m ready to go. Thanks for taking care of me."
    },
    {
      "turn_number": 23,
      "time": "2159-12-11 08:10:00",
      "speaker": "Doctor",
      "text": "You’re welcome. You did great with the procedure. Just take it easy for a few days, stick to your meds, and we’ll see how the next scan looks."
    },
    {
      "turn_number": 24,
      "time": "2159-12-11 08:11:00",
      "speaker": "Patient",
      "text": "One more thing—my leg swelling seems a bit worse. Is that normal?"
    },
    {
      "turn_number": 25,
      "time": "2159-12-11 08:12:00",
      "speaker": "Doctor",
      "text": "You do have mild increase in your right leg edema, likely from a bit of salt in your diet before admission. Keep taking your diuretics and monitor it. If it gets much worse, let your doctor know."
    },
    {
      "turn_number": 26,
      "time": "2159-12-11 08:13:00",
      "speaker": "Patient",
      "text": "Okay, I’ll watch it. Thanks again."
    },
    {
      "turn_number": 27,
      "time": "2159-12-11 08:14:00",
      "speaker": "Doctor",
      "text": "Take care, Mr. ___. You’re all set to be discharged. Someone will bring your prescriptions shortly."
    },
    {
      "turn_number": 28,
      "time": "2159-12-11 08:15:00",
      "speaker": "Patient",
      "text": "Appreciate it. See you next time."
    }
  ],
  "summary": {
    "admission_start": "2159-12-10 17:03:00",
    "admission_end": "2159-12-11 12:00:00",
    "summary_paragraph": "Mr. ___, a male with hepatitis C-related cirrhosis and multifocal hepatocellular carcinoma, was admitted for post-procedural observation following his fifth transarterial chemoembolization (TACE) for a 2.7 cm tumor in hepatic segment VIII. The procedure was successfully performed via the right hepatic artery using doxorubicin-loaded Oncozene beads, with minor additional supply noted from the left hepatic artery that was not amenable to treatment. He tolerated the intervention well without immediate complications, remained hemodynamically stable, and reported no pain, nausea, or procedural site issues. His cirrhosis, diabetes, and other comorbidities were managed with continuation of home medications. A mild increase in right leg edema was noted, attributed to dietary salt intake. He was discharged home the following day in stable condition with instructions to monitor for fever or pain, continue all prescribed medications, and follow up with his liver team in two weeks for evaluation and planning.",
    "problems": [
      "Malignant neoplasm of liver, primary",
      "Alcoholic cirrhosis of liver",
      "Unspecified viral hepatitis C without hepatic coma",
      "Coronary atherosclerosis of native coronary artery",
      "Diabetes mellitus without mention of complication, type II or unspecified type, not stated as uncontrolled",
      "Edema",
      "Anemia, unspecified",
      "Old myocardial infarction",
      "Aortocoronary bypass status",
      "Portal hypertension",
      "Personal history of tobacco use",
      "Esophageal reflux",
      "Other and unspecified hyperlipidemia",
      "Long-term (current) use of aspirin"
    ]
  }
}
